            RandomDatasetKeys.FilePath(key, index, out allocation);
        return new Sink(createParts ? Rnd981v.CreateDatasetWriter(route, filePath, files, options)
            : Rnd981v.CreateDatasetWriter(route, files, options));
    }

    sealed class Sink(Rnd981v.DatasetWriter writer) : IRandomDatasetSink
    {
        public void Queue(object row) => writer.Queue((Rnd981v)row);
        public void Dispose() => writer.Dispose();
    }
}